package com.markettwits.sportsouce.start.domain

import com.markettwits.sportsouce.start.cloud.model.start.fields.Distance
import com.markettwits.sportsouce.start.cloud.model.start.fields.DistinctDistance
import com.markettwits.sportsouce.start.cloud.model.start.fields.Organizer
import com.markettwits.sportsouce.start.presentation.membres.models.StartMembersUi
import com.markettwits.sportsouce.start.presentation.result.model.MemberResult

data class StartItem(
    val id: Int,
    val title: String,
    val startPlace: String,
    val slug: String,
    val image: String,
    val startMembersUi: List<StartMembersUi>,
    val kindOfSports: List<KindOfSport>,
    val sponsors: List<Sponsor>,
    val startSeries: StartSeries,
    val startStatus: StartStatus,
    val startData: String,
    val startAlbum: List<Album>,
    val startTime: String,
    val description: String,
    val paymentDisabled: Boolean,
    val regLink: String,
    val regOnSite: Boolean,
    val reviewState: ReviewState,
    val distanceInfoNew: List<DistinctDistance>,
    val conditionDetails: List<ConditionDetail>,
    val distanceMapNew: List<Distance>,
    val paymentType: String,
    val organizers: List<Organizer>,
    val membersResults: List<MemberResult>,
    val conditionFile: ConditionFile,
    val commentsRemote: Comments,
    val result: List<Result>,
    val usefulLinks: List<Result>,
    val startTimes: StartTimes,
) {
    sealed class ConditionDetail(open val value: String) {
        data class Regulation(override val value: String) : ConditionDetail(value)
        data class Statement(override val value: String) : ConditionDetail(value)
    }

    sealed class StartSeries {
        data object Empty : StartSeries()
        data class Value(
            val id: Int,
            val name: String,
            val description: String,
        ) : StartSeries()
    }

    sealed class ConditionFile {
        data class Base(val url: String) : ConditionFile()
        data object Empty : ConditionFile()
    }

    data class Sponsor(
        val id: Int,
        val name: String,
        val imageUrl: String,
        val link: String,
    )

    data class KindOfSport(
        val id: Int,
        val name: String,
    )

    data class StartStatus(
        val code: Int,
        val name: String,
    )

    data class Album(
        val id: Int,
        val startId: Int,
        val photos: List<Photo>,
        val name: String,
    ) {
        data class Photo(
            val id: Int,
            val photoId: Int,
            val imageUrl: String,
            val tags: Map<Int, String>,
        )
    }

    data class StartTimes(
        val beginningRegistry: String,
        val endRegistry: String,
        val beginningStart: String,
        val endStart: String,
    )

    data class Result(
        val id: Int,
        val name: String,
        val url: String,
    )

    sealed class ReviewState {
        data object NoReviews : ReviewState()
        data object LowRating : ReviewState()
        data class Rated(val scores: ReviewScores) : ReviewState()
    }

    data class ReviewScores(
        val review: Float,
        val location: Int,
        val road: Int,
        val team: Int,
    )

    data class Comments(
        val id: Int,
        val rows: List<Row>,
    ) {
        data class Row(
            val comment: String,
            val countSub: Int,
            val createdAt: String,
            val id: Int,
            val personId: String,
            val replies: List<Reply>,
            val updatedAt: String,
            val user: User,
        )

        data class User(
            val id: Int,
            val name: String,
            val photo: String?,
            val surname: String,
        )

        data class Reply(
            val comment: String,
            val createdAt: String,
            val id: Int,
            val user: User,
        )
    }
}