@Composable
fun ShopItemCardCompact(
    modifier: Modifier = Modifier,
    shopItem: ShopItem,
    onItemClick: (ShopItem) -> Unit,
    cardWidth: Dp = 140.dp,
    cardHeight: Dp = 230.dp,
) {
    Box(
        modifier = modifier
            .padding(2.dp)
            .clip(Shapes.large)
            .width(cardWidth)
            .height(cardHeight)
            .background(MaterialTheme.colorScheme.primary)
            .clickable {
                onItemClick(shopItem)
            }
    ) {
        Column {
            ImageCard(
                modifier = Modifier
                    .clip(Shapes.large)
                    .align(Alignment.CenterHorizontally)
                    .weight(0.65f),
                image = shopItem.visual.imageUrl,
            )
            Spacer(modifier = Modifier.padding(2.dp))
            ShowCardPrice(
                modifier = Modifier
                    .padding(4.dp)
                    .align(Alignment.Start)
                    .weight(0.3f),
                currentPrice = shopItem.price.currentPrice,
                previousPrice = shopItem.price.previousPrice,
                discount = shopItem.price.discount,
                title = shopItem.visual.displayName
            )
        }
    }
}

@Composable
private fun ImageCard(
    modifier: Modifier = Modifier,
    image: List<String>,
) {
    Box(modifier = modifier) {
        if (image.isNotEmpty()) {
            SubcomposeAsyncImage(
                modifier = Modifier.fillMaxSize(),
                model = imageRequestCrossfade(image.first()),
                filterQuality = FilterQuality.High,
                contentDescription = "",
                alignment = Alignment.Center,
                contentScale = ContentScale.Fit,
                clipToBounds = false,
                loading = {
                    Box(
                        modifier = modifier
                            .shimmer(
                                tiltAngle = 30,
                                gradientColors = listOf(
                                    Color.Transparent,
                                    MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.1f),
                                    Color.Transparent,
                                )
                            ).background(MaterialTheme.colorScheme.primaryContainer)
                    )
                },
                success = {
                    SubcomposeAsyncImageContent(
                        modifier = Modifier.background(Color.White)
                    )
                }
            )
        } else {
            Box(
                modifier = Modifier
                    .fillMaxSize()
            ) {
                Icon(
                    modifier = Modifier
                        .size(40.dp)
                        .align(Alignment.Center),
                    imageVector = Icons.Default.Photo,
                    tint = MaterialTheme.colorScheme.outline,
                    contentDescription = ""
                )
            }
        }
    }
}

@Composable
private fun ShowCardPrice(
    modifier: Modifier,
    currentPrice: String,
    previousPrice: String?,
    discount: Int?,
    title: String,
) {
    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.Start,
    ) {
        Row(
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = "$currentPrice ₽",
                color = MaterialTheme.colorScheme.secondary,
                textAlign = TextAlign.Start,
                overflow = TextOverflow.Ellipsis,
                maxLines = 1,
                fontSize = 16.sp,
                fontFamily = FontNunito.bold(),
            )
            Spacer(modifier = Modifier.padding(horizontal = 4.dp))
            if (!previousPrice.isNullOrEmpty()) {
                Text(
                    text = "$previousPrice₽",
                    color = MaterialTheme.colorScheme.outline,
                    textAlign = TextAlign.Start,
                    maxLines = 1,
                    textDecoration = TextDecoration.LineThrough,
                    overflow = TextOverflow.Ellipsis,
                    fontSize = 14.sp,
                    fontFamily = FontNunito.regular(),
                )
            }
            Spacer(modifier = Modifier.padding(horizontal = 4.dp))
            if (!previousPrice.isNullOrEmpty()) {
                Text(
                    text = "-$discount%",
                    color = MaterialTheme.colorScheme.secondary,
                    textAlign = TextAlign.Start,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    fontSize = 14.sp,
                    lineHeight = 12.sp,
                    fontFamily = FontNunito.medium(),
                )
            }
        }
        Text(
            text = title,
            color = MaterialTheme.colorScheme.tertiary,
            overflow = TextOverflow.Ellipsis,
            maxLines = 2,
            lineHeight = 14.sp,
            softWrap = true,
            textAlign = TextAlign.Start,
            fontSize = 14.sp,
            fontFamily = FontNunito.medium(),
        )
    }
}
